import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] t = {3, 1, 2, 4};
        int[] r = new int[4];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < 4; i++) {
            while (!st.isEmpty() && t[st.peek()] < t[i]) {
                int j = st.pop();
                r[j] = i - j;
            }
            st.push(i);
        }
        System.out.println(Arrays.toString(r));
    }
}

